import java.time.*;import java.util.*;import java.util.concurrent.*;
import com.example.editor.grammar.*;import com.example.editor.grammar.application.*;import com.example.editor.grammar.core.*;import com.example.editor.grammar.diagnostic.*;import com.example.editor.grammar.runtime.*;import com.example.editor.textual.runtime.*;import com.example.editor.textual.source.*;

public final class GrammarV43297StressHarness {
 private static int checks=0;
 public static void main(String[]args)throws Exception{
   positions();pathsAndHashes();referenceDiagnostics();cyclesAndLimits();textualCanonical();textualReconciliation();fuzz();concurrency();benchmark();
   System.out.println("GRAMMAR_V43297_STRESS PASS checks="+checks);
 }
 static void positions(){String s="a\r\nb😀c\rd\ne";SourceTextIndex idx=new SourceTextIndex(s);eq(idx.position(0),new TextPosition(0,0),"origin");int emoji=s.indexOf("😀");eq(idx.position(emoji),new TextPosition(1,1),"emoji start UTF16");eq(idx.position(emoji+2),new TextPosition(1,3),"emoji end UTF16");eq(idx.position(s.indexOf('d')),new TextPosition(2,0),"CR line");eq(idx.position(s.indexOf('e')),new TextPosition(3,0),"LF line");for(int i=0;i<=s.length();i++){TextPosition p=idx.position(i);int round=idx.offset(p);ok(round==i||round==i+1,"offset roundtrip "+i);} }
 static void pathsAndHashes(){for(String bad:List.of("../x.langium","/x","C:/x","a/../../b","~/.x","a:b")){boolean failed=false;try{GrammarPathPolicy.requirePortableRelative(bad,"path");}catch(IllegalArgumentException e){failed=true;}ok(failed,"reject "+bad);}var a=doc("a","a.langium","A: 'a';");var b=doc("b","b.langium","B: 'b';");eq(GrammarHashing.sources(List.of(a,b)),GrammarHashing.sources(List.of(b,a)),"hash order independent");boolean collision=false;try{new GeneratedGrammarProject("p",Map.of("../evil","x"),Map.of());}catch(IllegalArgumentException e){collision=true;}ok(collision,"generated traversal rejected");}
 static void referenceDiagnostics(){GrammarProperties p=new GrammarProperties();p.setAutomaticFixMinimumScore(.80);p.setAutomaticFixMinimumMargin(.05);GrammarSourceAnalyzer a=new GrammarSourceAnalyzer(p);String source="grammar Test\nentry Model: target=Custmer;\nCustomer: 'customer';\nOther: target=customer;\n";var g=grammar("g",GrammarTechnology.LANGIUM,List.of(doc("main","main.langium",source)));var r=a.analyze(g,new GrammarAnalysisRequest(g.id(),1,GrammarAnalysisMode.FAST,List.of("main"),g.documents(),g.toolchainProfileId()));ok(r.diagnostics().stream().anyMatch(d->d.code().equals("REFERENCE_NOT_FOUND")),"not found classified");ok(r.diagnostics().stream().anyMatch(d->d.code().equals("REFERENCE_CASE_MISMATCH")),"case mismatch classified");var typo=r.diagnostics().stream().filter(d->d.metadata().getOrDefault("reference","").contains("Custmer")).findFirst().orElseThrow();ok(!typo.candidates().isEmpty()&&typo.candidates().get(0).name().equals("Customer"),"candidate Customer");ok(r.codeActions().stream().anyMatch(c->c.title().contains("Customer")),"structured code action");
 String dup="grammar D\nA:'a';\nA:'b';\n";var dg=grammar("dup",GrammarTechnology.LANGIUM,List.of(doc("d","d.langium",dup)));ok(a.analyze(dg,new GrammarAnalysisRequest(dg.id(),1,GrammarAnalysisMode.FAST,List.of(),dg.documents(),dg.toolchainProfileId())).diagnostics().stream().anyMatch(d->d.code().equals(GrammarDiagnosticCatalog.DUPLICATE_SYMBOL)),"duplicate rule");}
 static void cyclesAndLimits(){GrammarProperties p=new GrammarProperties();p.setMaximumImportDepth(16);p.setMaximumDiagnostics(7);GrammarSourceAnalyzer a=new GrammarSourceAnalyzer(p);var ga=doc("a","a.langium","import 'b.langium'\nA: B;");var gb=doc("b","b.langium","import 'a.langium'\nB: A;");var g=grammar("cyc",GrammarTechnology.LANGIUM,List.of(ga,gb));var r=a.analyze(g,new GrammarAnalysisRequest(g.id(),1,GrammarAnalysisMode.NORMAL,List.of(),g.documents(),g.toolchainProfileId()));ok(r.diagnostics().stream().anyMatch(d->d.code().equals("REFERENCE_CYCLE")),"import cycle");StringBuilder many=new StringBuilder("grammar Many\n");for(int i=0;i<100;i++)many.append("R").append(i).append(": Missing").append(i).append(";\n");var mg=grammar("many",GrammarTechnology.LANGIUM,List.of(doc("m","m.langium",many.toString())));var mr=a.analyze(mg,new GrammarAnalysisRequest(mg.id(),1,GrammarAnalysisMode.NORMAL,List.of(),mg.documents(),mg.toolchainProfileId()));ok(mr.diagnostics().size()<=7,"diagnostic cap");ok(mr.diagnostics().stream().anyMatch(d->d.code().equals("GRAMMAR_DIAGNOSTIC_LIMIT")),"diagnostic cap evidence");}
 static void textualCanonical(){var binding=new GrammarSemanticBinding("main:rule:Customer:0","RULE","Customer","CLASS",1,"TEST",Map.of("grammarName","Customer"));var snap=new GrammarCompilationSnapshot("snap","g",1,"012345678901234567890123456789012345678901234567890123456789abcd",GrammarTechnology.LANGIUM,"langium","langium-4.3-browser",CompilationStatus.SUCCESS,List.of(),new GrammarSemanticBindingMap("1.0",List.of(binding),Map.of()),new GrammarRuntimeDescriptor("LSP","Model",List.of(".g"),"","",Map.of()),new GeneratedGrammarProject("p",Map.of("main.langium","x"),Map.of()),Map.of(),Instant.now(),Map.of());NeutralTextualModelParser p=new NeutralTextualModelParser();var good=p.parse(1,List.of(new TextualModelSourceDocument("model","model.g","Customer c1 { name=\"Ada\" }\nCustomer c2 { owner=c1 }",1)),snap);ok(good.valid(),"textual valid");ok(good.semanticModel()!=null&&good.semanticModel().elements().size()==2,"canonical elements");ok(good.semanticModel().relations().size()==1,"canonical relation");ok(good.sourceMap().stream().anyMatch(e->!e.grammarRuleId().isBlank()),"source map grammar rule");var bad=p.parse(2,List.of(new TextualModelSourceDocument("model","model.g","Customer c1 { owner=missing }",2)),snap);ok(!bad.valid()&&bad.semanticModel()==null,"broken draft not promoted");}

 static void textualReconciliation(){
   var binding=new GrammarSemanticBinding("main:rule:Customer:0","RULE","Customer","CLASS",1,"TEST",Map.of("grammarName","Customer"));
   var snap=new GrammarCompilationSnapshot("snap-r","g",1,"012345678901234567890123456789012345678901234567890123456789abcd",GrammarTechnology.LANGIUM,"langium","langium-4.3-browser",CompilationStatus.SUCCESS,List.of(),new GrammarSemanticBindingMap("1.0",List.of(binding),Map.of()),new GrammarRuntimeDescriptor("LSP","Model",List.of(".g"),"","",Map.of()),new GeneratedGrammarProject("p",Map.of("main.langium","x"),Map.of()),Map.of(),Instant.now(),Map.of());
   NeutralTextualModelParser parser=new NeutralTextualModelParser();
   var docs=List.of(new TextualModelSourceDocument("model","model.g","Customer c1 { name=\"Ada\" }\r\nCustomer c2 { owner=c1 }",1));
   var parsed=parser.parse(1,docs,snap);ok(parsed.valid(),"reconciliation baseline valid");
   var before=parsed.semanticModel();
   var changedElements=before.elements().stream().map(e->e.id().equals("c1")?new com.example.editor.validation.model.CanonicalModelElement(e.id(),e.classId(),Map.of("name","Grace"),e.annotations()):e).toList();
   var changedRelations=before.relations().stream().map(r->new com.example.editor.validation.model.CanonicalModelRelation(r.id(),r.relationId(),r.sourceElementId(),"c2",r.annotations())).toList();
   var candidate=new com.example.editor.validation.model.CanonicalModelDocument(before.schemaVersion(),before.id(),before.metamodelId(),before.metamodelEtag(),before.name(),before.rootElementIds(),changedElements,changedRelations,before.annotations());
   var reconciler=new TextualCanonicalReconciliationService();var result=reconciler.reconcile(2,before,candidate,docs,parsed.sourceMap(),snap);
   ok(result.safe(),"attribute/reference reconciliation safe: "+result.reason());ok(result.edits().size()==2,"two textual edits");ok(result.documents().get(0).content().contains("name=\"Grace\""),"attribute projected");ok(result.documents().get(0).content().contains("owner=c2"),"reference projected");ok(result.parsed()!=null&&reconciler.semanticallyEquivalent(candidate,result.parsed().semanticModel()),"reparse semantic equivalence");
   var extra=new ArrayList<com.example.editor.validation.model.CanonicalModelElement>(candidate.elements());extra.add(new com.example.editor.validation.model.CanonicalModelElement("c3","Customer",Map.of(),Map.of()));
   var structural=new com.example.editor.validation.model.CanonicalModelDocument(candidate.schemaVersion(),candidate.id(),candidate.metamodelId(),candidate.metamodelEtag(),candidate.name(),candidate.rootElementIds(),extra,candidate.relations(),candidate.annotations());
   ok(!reconciler.reconcile(3,before,structural,docs,parsed.sourceMap(),snap).safe(),"structural reconciliation rejected");
 }
 static void fuzz(){GrammarProperties p=new GrammarProperties();p.setMaximumDiagnostics(50);GrammarSourceAnalyzer a=new GrammarSourceAnalyzer(p);Random rnd=new Random(43297);String chars="abcXYZ0123:;[]{}()=|'\\\" \r\n😀";for(int n=0;n<2500;n++){int len=rnd.nextInt(320);StringBuilder s=new StringBuilder();for(int i=0;i<len;i++)s.append(chars.charAt(rnd.nextInt(chars.length())));var g=grammar("f"+n,GrammarTechnology.values()[n%3],List.of(doc("d","f"+n+ext(GrammarTechnology.values()[n%3]),s.toString())));try{a.analyze(g,new GrammarAnalysisRequest(g.id(),n,GrammarAnalysisMode.FAST,List.of(),g.documents(),g.toolchainProfileId()));}catch(StackOverflowError|OutOfMemoryError e){throw new AssertionError("fuzz resource failure "+n,e);}checks++;}}
 static void concurrency()throws Exception{GrammarSourceAnalyzer a=new GrammarSourceAnalyzer(new GrammarProperties());StringBuilder s=new StringBuilder("grammar C\n");for(int i=0;i<500;i++)s.append("R").append(i).append(": 'x';\n");var g=grammar("concurrent",GrammarTechnology.LANGIUM,List.of(doc("d","c.langium",s.toString())));ExecutorService pool=Executors.newFixedThreadPool(12);try{List<Future<String>>f=new ArrayList<>();for(int i=0;i<120;i++)f.add(pool.submit(()->a.analyze(g,new GrammarAnalysisRequest(g.id(),1,GrammarAnalysisMode.FAST,List.of(),g.documents(),g.toolchainProfileId())).sourceHash()));String expected=f.get(0).get();for(Future<String>x:f)eq(x.get(),expected,"concurrent deterministic");}finally{pool.shutdownNow();}}
 static void benchmark(){GrammarSourceAnalyzer a=new GrammarSourceAnalyzer(new GrammarProperties());StringBuilder s=new StringBuilder("grammar Big\n");for(int i=0;i<5000;i++)s.append("Rule").append(i).append(": 'r").append(i).append("';\n");var g=grammar("big",GrammarTechnology.LANGIUM,List.of(doc("d","big.langium",s.toString())));long start=System.nanoTime();var r=a.analyze(g,new GrammarAnalysisRequest(g.id(),1,GrammarAnalysisMode.FAST,List.of(),g.documents(),g.toolchainProfileId()));long ms=TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-start);ok(r.symbols().size()>=5000,"5000 rules recognized");ok(ms<5000,"5000 rule budget ms="+ms);System.out.println("benchmark.rules5000.ms="+ms);}
 static GrammarDefinitionModel grammar(String id,GrammarTechnology tech,List<GrammarSourceDocument>docs){String profile=switch(tech){case LANGIUM->"langium-4.3-browser";case XTEXT->"xtext-2.44-lsp";case ANTLR->"antlr-4.13.2-java";};return new GrammarDefinitionModel("1.0",id,id,tech,GrammarAuthoringMode.GRAMMAR_FIRST,"",profile,docs.get(0).id(),"Model",docs,GrammarSemanticBindingMap.empty(),"",Map.of(),Map.of());}
 static GrammarSourceDocument doc(String id,String path,String content){return new GrammarSourceDocument(id,path,"",content,"",false,false);}static String ext(GrammarTechnology t){return t==GrammarTechnology.ANTLR?".g4":t==GrammarTechnology.XTEXT?".xtext":".langium";}
 static void ok(boolean v,String label){checks++;if(!v)throw new AssertionError(label);}static void eq(Object a,Object b,String label){ok(Objects.equals(a,b),label+" expected="+b+" actual="+a);}
}
